import React from 'react';
import Navbar from './components/Navbar';
import ParentSection from './components/ParentSection';
import 'katex/dist/katex.min.css';

function App() {
  const parentSections = [
    {
      id: 'main-functions',
      title: 'Main Functions',
      sections: [
        {
          id: 'some-samples',
          title: 'Some Samples',
          content: [
            {
              type: 'paragraph',
              text: 'We are using the DeepFloyd IF model, version 1.0, which is a state-of-the-art text-to-image generation framework. The model operates in two stages:'
            },
            {
              type: 'list',
              items: [
                {
                  text: 'Stage I: The base model generates initial low-resolution images (64x64 or 256x256) from a given text prompt. This stage captures the semantics of the prompt and forms the foundation for further refinement.'
                },
                {
                  text: 'Stage II: The super-resolution (SR) model takes the low-resolution images from Stage I and enhances them to higher resolutions, up to 1024x1024 pixels. This stage ensures high-quality details and sharpness in the generated images.'
                },
              ]
            },
            {
              type: 'paragraph',
              text: 'Here are some sample images generated using the DeepFloyd IF model with the respective text prompts.'
            },
            {
              type: 'image-grid',
              columns: 3,
              images: [
                {
                  title: 'Text Prompt: "A futuristic cityscape under a pink sunset"',
                  imageUrl: `${process.env.PUBLIC_URL}/images/sample1.jpg`
                },
                {
                  title: 'Text Prompt: "A cat sitting on a vibrant green meadow"',
                  imageUrl: `${process.env.PUBLIC_URL}/images/sample2.jpg`
                },
                {
                  title: 'Text Prompt: "A surreal desert landscape with a giant clock"',
                  imageUrl: `${process.env.PUBLIC_URL}/images/sample3.jpg`
                },
                {
                  title: 'Text Prompt: "An astronaut riding a horse on Mars"',
                  imageUrl: `${process.env.PUBLIC_URL}/images/sample4.jpg`
                },
                {
                  title: 'Text Prompt: "A magical forest with glowing mushrooms"',
                  imageUrl: `${process.env.PUBLIC_URL}/images/sample5.jpg`
                },
                {
                  title: 'Text Prompt: "A serene beach with crystal-clear waters"',
                  imageUrl: `${process.env.PUBLIC_URL}/images/sample6.jpg`
                },
              ]
            }
          ]
        },
        { id: 'forward-process', title: 'Forward Process', content: [] },
        { id: 'classical-denoising', title: 'Classical Denoising', content: [] },
        { id: 'one-step-denoising', title: '1 Step Denoising', content: [] },
        { id: 'iterative-denoising', title: 'Iterative Denoising', content: [] },
        { id: 'diffusion-sampling', title: 'Diffusion Model Sampling', content: [] },
        { id: 'classifier-guidance', title: 'Classifier Free Guidance', content: [] },
      ],
    },
    {
      id: 'more-applications',
      title: 'More Applications',
      sections: [
        { id: 'image-to-image', title: 'Image to Image Translation', content: [] },
        { id: 'visual-anagrams', title: 'Visual Anagrams', content: [] },
        { id: 'hybrid-images', title: 'Hybrid Images', content: [] },
      ],
    },
  ];

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-gradient-to-b from-black via-gray-900 to-black text-gray-300">
      {/* Navbar */}
      <Navbar parentSections={parentSections} />

      {/* Main Content */}
      <div className="flex-1 px-4 sm:px-2 lg:px-8 py-8 md:ml-64 w-full">
        <h1 className="text-3xl sm:text-2xl lg:text-4xl font-bold text-center mb-12 text-white">
          Diffusion Models
        </h1>

        {/* Render Parent Sections */}
        {parentSections.map((parent) => (
          <ParentSection
            key={parent.id}
            id={parent.id}
            title={parent.title}
            sections={parent.sections}
          />
        ))}
      </div>
    </div>
  );
}

export default App;
